\begin{ex}%[8D1N1]
Tìm tổng của các đơn thức đồng dạng:

a) ${2 x}$ và ${x}$

b) ${- 9 x y^{9}}$ và ${x y^{9}}$

c) ${x^{9} y^{8} z}$ và ${4 x^{9} y^{8} z}$
\loigiai{
a) $2 x+x = 3 x$\\
b) $- 9 x y^{9}+x y^{9} =- 8 x y^{9}$\\
c) $x^{9} y^{8} z + 4 x^{9} y^{8} z =5 x^{9} y^{8} z $
}\end{ex}

\begin{ex}%[8D1N1]
Tìm tổng của các đơn thức đồng dạng:

a) ${- 3 x}$ và ${x}$

b) ${- 3 x y}$ và ${x y}$

c) ${x y z}$ và ${- 2 x y z}$
\loigiai{
a) $- 3 x+x = - 2 x$\\
b) $- 3 x y+x y =- 2 x y$\\
c) $x y z + - 2 x y z =- x y z $
}\end{ex}
